TITLE: Set a Session Cookie via API Route in Next.js Pages Router
DESCRIPTION: This snippet illustrates how to create an API route in the Next.js Pages Router to set a session cookie. It receives data, encrypts it, and uses the `cookie` library's `serialize` function to create a secure, HTTP-only cookie. The cookie is then added to the response headers.

SOURCE: https://github.com/vercel/next.js/blob/canary/docs/01-app/02-guides/authentication.mdx#_snippet_19

LANGUAGE: typescript
CODE:
```
import { serialize } from 'cookie'
import type { NextApiRequest, NextApiResponse } from 'next'
import { encrypt } from '@/app/lib/session'

export default function handler(req: NextApiRequest, res: NextApiResponse) {
  const sessionData = req.body
  const encryptedSessionData = encrypt(sessionData)

  const cookie = serialize('session', encryptedSessionData, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    maxAge: 60 * 60 * 24 * 7, // One week
    path: '/',
  })
  res.setHeader('Set-Cookie', cookie)
  res.status(200).json({ message: 'Successfully set cookie!' })
}
```

