    console.error('JWT verification failed:', error)
    return false
  }
}

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl

  // Skip middleware for static assets, API routes, and Next.js internals
  if (
    pathname.startsWith('/api/') ||
    pathname.startsWith('/_next/') ||
    pathname.startsWith('/_vercel/') ||
    pathname.includes('.')
  ) {
    return NextResponse.next()
  }

  // Check if the current route is protected or public
  const isProtectedRoute = protectedRoutes.some(route => 
    pathname.startsWith(route)
  )
  const isPublicRoute = publicRoutes.some(route => 
    pathname === route || pathname.startsWith(route)
  )

  // Get JWT token from cookies
  const token = request.cookies.get('auth-token')?.value

  // Verify JWT token
  let isAuthenticated = false
  if (token) {
    isAuthenticated = await verifyJWT(token)
  }

  // Redirect logic
  if (isProtectedRoute && !isAuthenticated) {
    // User is trying to access a protected route without authentication
    // Redirect to login page with the original URL as a redirect parameter
    const loginUrl = new URL('/login', request.url)
    loginUrl.searchParams.set('redirect', pathname)
    return NextResponse.redirect(loginUrl)
  }

  if (isPublicRoute && isAuthenticated && pathname === '/login') {
    // User is already authenticated but trying to access login page
    // Redirect to dashboard or home page
    return NextResponse.redirect(new URL('/dashboard', request.url))
  }

  // Continue with the request
  return NextResponse.next()
}

// Configure the middleware matcher
export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - api (API routes)
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     * - sitemap.xml (sitemap file)
     * - robots.txt (robots file)
     */
    '/((?!api|_next/static|_next/image|favicon.ico|sitemap.xml|robots.txt).*)',
  ],
}

