"use client"

import React, { useState } from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Label } from "@/components/ui/label"

export default function CreatePostPage() {
  const [title, setTitle] = useState("")
  const [content, setContent] = useState("")
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Check if both fields have content to enable/disable the publish button
  const isFormValid = title.trim().length > 0 && content.trim().length > 0

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!isFormValid) return

    setIsSubmitting(true)

    try {
      // Simulate API call to create post
      await new Promise(resolve => setTimeout(resolve, 1000))

      console.log("Post created:", { title, content })

      // Reset form after successful submission
      setTitle("")
      setContent("")

      alert("Post published successfully!")
    } catch (error) {
      console.error("Error creating post:", error)
      alert("Failed to publish post. Please try again.")
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="max-w-2xl mx-auto p-6">
      <div className="space-y-6">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Create New Post</h1>
          <p className="text-muted-foreground mt-2">
            Share your thoughts with the community
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Title Input */}
          <div className="space-y-2">
            <Label htmlFor="title">Title</Label>
            <Input
              id="title"
              type="text"
              placeholder="Enter your post title..."
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full"
            />
            <p className="text-sm text-muted-foreground">
              {title.length}/100 characters
            </p>
          </div>

          {/* Content Textarea */}
          <div className="space-y-2">
            <Label htmlFor="content">Content</Label>
            <Textarea
              id="content"
              placeholder="Write your post content here..."
              value={content}
              onChange={(e) => setContent(e.target.value)}
              className="min-h-[200px] w-full resize-none"
            />
            <p className="text-sm text-muted-foreground">
              {content.length}/1000 characters
            </p>
          </div>

          {/* Form Status */}
          <div className="flex items-center justify-between">
            <div className="text-sm text-muted-foreground">
              {!isFormValid && (
                <span className="text-orange-600">
                  {!title.trim() && !content.trim() 
                    ? "Please add a title and content to publish"
                    : !title.trim() 
                    ? "Please add a title to publish"
                    : "Please add content to publish"}
                </span>
              )}
              {isFormValid && (
                <span className="text-green-600">Ready to publish!</span>
              )}
            </div>
          </div>

          {/* Action Buttons */}
          <div className="flex gap-3 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => {
                setTitle("")
                setContent("")
              }}
              disabled={isSubmitting}
            >
              Clear
            </Button>

            <Button
              type="submit"
              disabled={!isFormValid || isSubmitting}
              className="min-w-[120px]"
            >
              {isSubmitting ? (
                <>
                  <div className="mr-2 h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
                  Publishing...
                </>
              ) : (
                "Publish"
              )}
            </Button>
          </div>
        </form>

        {/* Preview Section */}
        {(title || content) && (
          <div className="mt-8 p-6 border rounded-lg bg-muted/50">
            <h2 className="text-lg font-semibold mb-4">Preview</h2>
            <div className="space-y-3">
              {title && (
                <h3 className="text-xl font-semibold">{title}</h3>
              )}
              {content && (
                <p className="whitespace-pre-wrap text-muted-foreground">
                  {content}
                </p>
              )}
              {!title && !content && (
                <p className="text-muted-foreground italic">
                  Start typing to see a preview...
                </p>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

// Alternative simpler version without preview and extra features
export function SimpleCreatePost() {
  const [title, setTitle] = useState("")
  const [content, setContent] = useState("")

  const isFormValid = title.trim().length > 0 && content.trim().length > 0

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (isFormValid) {
      console.log("Post created:", { title, content })
      alert("Post published successfully!")
      setTitle("")
      setContent("")
    }
  }

  return (
    <div className="max-w-2xl mx-auto p-6">
      <h1 className="text-2xl font-bold mb-6">Create New Post</h1>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="title">Title</Label>
          <Input
            id="title"
            placeholder="Enter your post title..."
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
        </div>

        <div className="space-y-2">
          <Label htmlFor="content">Content</Label>
          <Textarea
            id="content"
            placeholder="Write your post content here..."
            value={content}
            onChange={(e) => setContent(e.target.value)}
            className="min-h-[150px]"
          />
        </div>

        <Button 
          type="submit" 
          disabled={!isFormValid}
          className="w-full"
        >
          Publish Post
        </Button>
      </form>
    </div>
  )
}

